#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6

# Run from the repo root so gh targets this repository.
cd "$(dirname "$0")/.."

# Secrets in this wizard live only in shell variables: they are piped to gh on
# stdin and never echoed or written to disk. Pointing ENV_FILE at /dev/null
# also stops ask_secret from offering (and re-uploading) a stale .env value.
ENV_FILE=/dev/null

# _secret_updated NAME prints when the repo secret NAME was last set; empty if
# it doesn't exist. The list is captured first, so a pipe can't cut gh short.
_secret_updated() {
  local list
  list=$(gh secret list --json name,updatedAt -q '.[] | "\(.name) \(.updatedAt)"' 2>/dev/null || true)
  awk -v n="$1" '$1 == n { print $2 }' <<<"$list"
}

# save_secret NAME VALUE BEFORE sets the secret, then proves it changed by
# comparing its timestamp with BEFORE (the timestamp ahead of this run).
save_secret() {
  local after
  set_secret "$1" "$2"
  after=$(_secret_updated "$1")
  if [[ -n "$after" && "$after" != "$3" ]]; then
    printf '  %s✓ verified%s %s is saved on %s\n' "$GREEN" "$RESET" "$1" "$REPO"
  else
    warn "couldn't confirm that $1 was saved; check: gh secret list"
  fi
}

# keep_secret NAME BEFORE reports a secret this run didn't change.
keep_secret() {
  if [[ -n "$2" ]]; then
    note "$1 left unchanged."
  else
    warn "$1 is not set on $REPO."
    SKIPPED+=("GitHub secret $1 (re-run this wizard)")
  fi
}

# _label_names lists the repository's label names, one per line.
_label_names() {
  gh label list --limit 1000 --json name -q '.[].name' 2>/dev/null || true
}

banner "ChargeOnSolar: software factory setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "GitHub CLI"
say "This wizard uses the GitHub CLI (gh) to set secrets, create labels and,"
say "optionally, protect main. It must be logged in as an admin of this repository."
if ! command -v gh >/dev/null 2>&1; then
  warn "gh is not installed. Install it (https://cli.github.com) and run this wizard again."
  exit 1
fi
if ! gh auth status >/dev/null 2>&1; then
  warn "gh is not logged in. Run: gh auth login, then run this wizard again."
  exit 1
fi
REPO=$(gh repo view --json nameWithOwner -q .nameWithOwner 2>/dev/null || true)
perm=$(gh repo view --json viewerPermission -q .viewerPermission 2>/dev/null || true)
if [[ -z "$REPO" ]]; then
  warn "gh can't tell which GitHub repository this is. Run the wizard from a clone of it."
  exit 1
fi
if [[ "$perm" != "ADMIN" ]]; then
  warn "You have ${perm:-no} access to $REPO; setting secrets needs ADMIN."
  exit 1
fi
printf '  %s✓ gh is ready%s  repository: %s (admin)\n' "$GREEN" "$RESET" "$REPO"
pause "Press Enter to continue"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Factory token: create it"
FACTORY_PAT=""
pat_before=$(_secret_updated FACTORY_PAT)
make_pat=true
if [[ -n "$pat_before" ]]; then
  printf '  %s✓ FACTORY_PAT is already set%s\n' "$GREEN" "$RESET"
  confirm "Create a new token and replace it (e.g. because it expired)?" || make_pat=false
fi
if $make_pat; then
  say "The workflows need a token of their own. The built-in Actions token isn't enough:"
  say "labels it applies start no workflows, so one agent can't hand work to the next,"
  say "and by default it cannot open pull requests."
  say ""
  open_url "https://github.com/settings/personal-access-tokens/new"
  step "Token name: ChargeOnSolar factory. Pick an expiration; re-run this wizard when it expires."
  step "Resource owner: ${REPO%%/*}."
  step "Repository access: Only select repositories → ${REPO#*/} (this one only)."
  step "Permissions → Repository permissions, set each to Read and write:"
  step "  Actions, Contents, Issues, Pull requests, Workflows."
  note "Metadata (read-only) is added automatically. Leave everything else at No access."
  step "Generate the token and copy it (it starts with github_pat_)."
  while true; do
    ask_secret FACTORY_PAT "Paste the token (hidden):"
    if [[ "$FACTORY_PAT" == github_pat_* ]]; then
      say "Checking that GitHub accepts the token…"
      # The token goes via a file descriptor, so it never shows in `ps`.
      code=$(curl -s -o /dev/null -w '%{http_code}' --max-time 15 \
        -H @<(printf 'Authorization: Bearer %s' "$FACTORY_PAT") \
        "https://api.github.com/repos/$REPO" || true)
      if [[ "$code" == "200" ]]; then
        printf '  %s✓ GitHub accepted the token%s\n' "$GREEN" "$RESET"
        note "This only proves the token is valid; GitHub can't show its permissions, so"
        note "double-check the five Read and write permissions on the token page."
        break
      fi
      warn "GitHub rejected the token (HTTP ${code:-no answer})."
    else
      warn "That doesn't look like a fine-grained token (they start with github_pat_)."
    fi
    if ! confirm "Paste it again?"; then FACTORY_PAT=""; break; fi
  done
fi
pause "Press Enter to continue"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Factory token: save it as FACTORY_PAT"
if [[ -n "$FACTORY_PAT" ]]; then
  save_secret FACTORY_PAT "$FACTORY_PAT" "$pat_before"
  FACTORY_PAT=""
else
  keep_secret FACTORY_PAT "$pat_before"
fi
pause "Press Enter to continue"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Claude token: CLAUDE_CODE_OAUTH_TOKEN"
CLAUDE_CODE_OAUTH_TOKEN=""
claude_before=$(_secret_updated CLAUDE_CODE_OAUTH_TOKEN)
make_claude=true
if [[ -n "$claude_before" ]]; then
  printf '  %s✓ CLAUDE_CODE_OAUTH_TOKEN is already set%s\n' "$GREEN" "$RESET"
  confirm "Generate a new token and replace it?" || make_claude=false
fi
if $make_claude; then
  say "The agents run on your Claude subscription, through a long-lived token."
  step "Open a SEPARATE terminal window and run:  claude setup-token"
  step "Log in in the browser it opens, then copy the token it prints."
  step "Close that terminal window afterwards, so the token isn't left on screen."
  ask_secret CLAUDE_CODE_OAUTH_TOKEN "Paste the token (hidden, empty to skip):"
fi
if [[ -n "$CLAUDE_CODE_OAUTH_TOKEN" ]]; then
  save_secret CLAUDE_CODE_OAUTH_TOKEN "$CLAUDE_CODE_OAUTH_TOKEN" "$claude_before"
  CLAUDE_CODE_OAUTH_TOKEN=""
  note "The token itself is checked by the first factory run, not here."
else
  keep_secret CLAUDE_CODE_OAUTH_TOKEN "$claude_before"
fi
pause "Press Enter to continue"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Trigger labels"
say "Putting one of these labels on an issue or PR starts a workflow. No workflow can"
say "create the label that starts it, so they're created here. Labels that already"
say "exist are left exactly as they are."
say ""
# name|colour|description, from the reference factory.
labels=(
  "agent:explore|7057FF|The factory explores this ticket"
  "agent:implement|1D76DB|Hand this issue to the implementer agent"
  "agent:review|0052CC|Ask the review workflow to read this pull request"
  "agent:implement-spec|3E4B9E|Work this spec through the implement-spec queue"
)
before=$(_label_names)
for entry in "${labels[@]}"; do
  IFS='|' read -r name color desc <<<"$entry"
  if grep -qxF "$name" <<<"$before"; then
    note "· $name already exists, left untouched"
  elif ! gh label create "$name" --color "$color" --description "$desc" >/dev/null 2>&1; then
    warn "couldn't create label $name"
  fi
done
after=$(_label_names)
for entry in "${labels[@]}"; do
  IFS='|' read -r name color desc <<<"$entry"
  if ! grep -qxF "$name" <<<"$after"; then
    SKIPPED+=("label $name: gh label create '$name' --color $color --description '$desc'")
  elif ! grep -qxF "$name" <<<"$before"; then
    printf '  %s✓ created%s label %s\n' "$GREEN" "$RESET" "$name"
  fi
done
pause "Press Enter to continue"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Optional: protect main"
say "The factory's token acts as you, and you're an admin. Branch protection that"
say "also applies to admins stops anything, the factory included, from pushing straight"
say "to main: every change has to arrive as a pull request."
note "It doesn't stop the token from merging a PR; the agents simply never do."
note "It also applies to you: your own changes to main will need a PR too."
say ""
BRANCH_SETTINGS="https://github.com/$REPO/settings/branches"
# gh api prints error bodies on stdout too, so check the exit code first.
requires_pr=$(gh api "repos/$REPO/branches/main/protection" \
  -q '.required_pull_request_reviews != null' 2>/dev/null) || requires_pr="error"
if [[ "$requires_pr" == "true" ]]; then
  printf '  %s✓ main already requires a pull request%s\n' "$GREEN" "$RESET"
elif [[ "$requires_pr" == "false" ]]; then
  warn "main already has branch protection, but it doesn't require a pull request."
  note "Left untouched so your existing rules aren't overwritten. Add the rule here:"
  open_url "$BRANCH_SETTINGS"
  SKIPPED+=("require a pull request on main: $BRANCH_SETTINGS")
# An unprotected branch is a 404, so gh exits non-zero even though its output
# says why; under pipefail, piping it into grep would always read as a failure.
elif [[ "$(gh api "repos/$REPO/branches/main/protection" 2>/dev/null || true)" != *'Branch not protected'* ]]; then
  warn "Couldn't read main's branch protection, so it's left alone."
  SKIPPED+=("branch protection on main: $BRANCH_SETTINGS")
elif confirm "Protect main so that merging needs a pull request?"; then
  if gh api -X PUT "repos/$REPO/branches/main/protection" --input - >/dev/null 2>&1 <<'JSON'
{
  "required_status_checks": null,
  "enforce_admins": true,
  "required_pull_request_reviews": { "required_approving_review_count": 0 },
  "restrictions": null
}
JSON
  then
    check=$(gh api "repos/$REPO/branches/main/protection" \
      -q '.required_pull_request_reviews != null' 2>/dev/null || true)
    if [[ "$check" == "true" ]]; then
      printf '  %s✓ verified%s main now requires a pull request\n' "$GREEN" "$RESET"
    else
      warn "Protection was sent, but reading it back failed; check $BRANCH_SETTINGS"
    fi
  else
    warn "GitHub refused to protect main."
    SKIPPED+=("branch protection on main: $BRANCH_SETTINGS")
  fi
else
  note "Skipped. Re-run this wizard any time to add it."
fi
pause "Press Enter to finish"

finish
say "Next: the factory is ready once its workflows are on main. See docs/agents/factory.md."
printf '\n'
}

run_wizard "$@"; exit
